const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let inputLines = [];
rl.on('line', (line) => {
  inputLines.push(line.trim());
}).on('close', () => {
  if (inputLines.length === 0) return;

  const firstLine = inputLines[0].split(' ').map(Number);
  const n = firstLine[0];
  const k = firstLine[1];
  const x = firstLine[2];

  const colors = inputLines[1].split(' ').map(Number);

  let maxDestroyed = 0;

  // Try inserting at every possible position (0 to n)
  for (let pos = 0; pos <= n; pos++) {
    // Create new array with inserted ball
    const newRow = [...colors.slice(0, pos), x, ...colors.slice(pos)];

    // Simulate the destruction process
    let destroyed = simulateDestruction(newRow);
    maxDestroyed = Math.max(maxDestroyed, destroyed);
  }

  console.log(maxDestroyed);
});

function simulateDestruction(row) {
  let currentRow = [...row];
  let totalDestroyed = 0;
  let changed = true;

  while (changed && currentRow.length > 0) {
    changed = false;
    let i = 0;

    while (i < currentRow.length) {
      let j = i;
      // Find the end of the contiguous segment of same color
      while (j < currentRow.length && currentRow[j] === currentRow[i]) {
        j++;
      }

      const segmentLength = j - i;

      if (segmentLength >= 3) {
        // Destroy this segment
        currentRow = [...currentRow.slice(0, i), ...currentRow.slice(j)];
        totalDestroyed += segmentLength;
        changed = true;
        break; // Restart scanning from beginning after destruction
      } else {
        i = j;
      }
    }
  }

  return totalDestroyed;
}
